Item.method_code:
/*
h4_change_list_stateを別関数から呼び出す形式に変更し、名前も
h4_change_state_listに変更
*/

/*
LCのポスト時に動作 現在のLCと同じステートをListにセットする。ListとLCの関連付けは
現在はないのでここで突合する
*/
Innovator inn = this.getInnovator();

// 引数取得 
string type = this.getProperty("type");
string id = this.getProperty("id");


// 現在のLCを取得
Item targetItem = inn.newItem(type, "get");
targetItem.setAttribute("select", "state");
targetItem.setProperty("id", id);
targetItem = targetItem.apply();

//WFの範囲ではLCはすべて同じで、名称も完全一致しているが、念のためListの番号に変換する
string LCName = targetItem.getProperty("state","");
string setListValue = "InProgress";

if(LCName == "InProgress"){ setListValue = "InProgress";}
else if(LCName == "RequestProvisionalApproval"){ setListValue = "RequestProvisionalApproval";}
else if(LCName == "ProvisionalApproved"){ setListValue = "ProvisionalApproved";}
else if(LCName == "RequestApproval"){ setListValue = "RequestApproval";}
else if(LCName == "Approved"){ setListValue = "Approved";}

//List変更
Item setTargetItem = inn.newItem(type,"edit");
//Item setTargetItem = inn.newItem(type,"update");
setTargetItem.setAttribute("id",id);
setTargetItem.setAttribute("version","0");
setTargetItem.setAttribute("serverEvents","0");//OnAfterUpdateのListにステート合わせる処理を無効に
setTargetItem.setProperty("h4_directaplist",setListValue);//マルQと必要資料で同名
setTargetItem = setTargetItem.apply();

return this;
